import { defineConfig } from "orval";

// Input is generated by `pnpm --filter @scvs/verification-svc run generate:openapi` (or the root `pnpm
// generate:api-client` convenience script, which runs both steps).
export default defineConfig({
  verifyApi: {
    input: {
      target: "../../services/verification-svc/openapi.json",
    },
    output: {
      mode: "single",
      target: "./src/generated/verify-api.ts",
      client: "react-query",
      httpClient: "axios",
      clean: true,
      // Generate `in: header` parameters as a typed argument. Off by default in orval, which is why
      // `getBuildLog` used to have no way to send its required `x-build-log-token` — and why the console
      // hand-wrote that request instead. It was never a limitation, only this default.
      headers: true,
      override: {
        mutator: {
          path: "./src/http.ts",
          name: "verifyApiClient",
        },
      },
    },
  },
});
